    "html.text.197": "关闭 ×",
    "html.text.198": "先看风雨，再改变风暴。交互引导会带你找到对应控件，可以边操作边阅读。",
    "html.div.aria-label.text.3": "操作流程：观察视场，定位台风，调节风雨",
    "html.text.199": "◉",
    "html.text.200": "观察视场",
    "html.text.201": "转动 · 缩放 · 换楼层",
    "html.text.202": "→",
