    "html.text.210": "开始交互引导 ",
    "html.text.211": "约 2 分钟 · 8 步",
    "html.guideChapters.aria-label.text.0": "按主题查看指引",
    "html.text.212": "随时点顶部“使用指南”重新打开。",
    "html.text.213": "配置编辑器 ↗",
    "html.text.214": "模型与限制",
    "html.text.215": "风场与操作说明",
    "html.button.aria-label.text.2": "关闭说明",
    "html.text.216": "关闭 ×",
    "html.text.217": "“去除雨雾”仅提高视觉通透度，保留雨丝与运动白色雾带，气象能见度读数不变。全屏默认锁定鼠标，移动鼠标即可无限环视，不受屏幕边缘限制；按 M 切换环视开关，关闭后可操作地图与控件，Esc 也可释放鼠标。若浏览器不支持鼠标锁定，则在画面边缘持续转动，仍可无限环绕；小地图可开启“拖动风暴中心”，开关与其他地图同步。滚轮支持 0.35–12 倍：最广垂直视场约 115°，附轻微桶形畸变与暗角。晴空 / 低降水有蓝天漫射、暖色阳光、地面反弹光与建筑树木投影；海面具有天空反射、视角相关水色和太阳碎光。",
    "html.text.218": "主视窗滚轮提供 0.35–12 倍望远镜缩放，点击倍率复位；高倍率下拖动更精细。“上帝视角”从当前位置进入自由飞行：点击视窗后 WASD 前后左右，WASD 始终沿水平面移动；Q/E 或 C/空格垂直升降，Shift 四倍加速，拖动可 360° 环视，俯仰范围 ±89°。飞行速度在视窗下方调节为 1–300 m/s，不受建筑、地面或高度限制，天气暂停时仍可飞行。风雨读数与地图视点跟随实际位置；“俯瞰楼群”进入海岸上空，“返回楼房”或重新选楼回到楼层视点，“归中”回到所选楼房位置。场景扩展内陆和南侧楼群，包含棕榈、阔叶树、层叠针叶树、窄冠树、长椅、花池及更多车辆。五座海边轻型棚屋在超过 120 kt 后累计受损，屋顶可被掀起、墙板倒伏，点击“恢复”重建。中低风速雨丝下落速度约 32 m/s，可见雨丝显著加密；强风下仍逐步转为横行碎雾。",
    "html.text.219": "默认从海岸公寓六层、距地坪 18 米（海拔 18.9 米）处观察。可在地图点选五座楼房，或在主视窗下方切换楼房与楼层，最高支持 40 层。拖动视窗或按方向键观察。地图默认拖动平移，仅开启“移动风暴中心”后点击或拖动才会移动风暴。滚轮或滑条缩放，地图宽度支持 0.24–3200 km；“楼群”查看住宅区，“全风场”显示外围圈。大地图显示实时一分钟持续风场，可悬停读数。",
    "html.text.220": "输入是台风静止时的最大 1 分钟持续风，范围 20–200 kt。低于 67 kt 不设风眼和眼墙，但中心仍减风；低于 34 kt 不设暴风圈。67–110 kt 眼墙增强、风眼减风从零连续发展，地图边界同步淡入。四个半径均可自定义，无效结构的设置暂时保留。暴风圈是可调结构边界，并非固定风速等值线。风眼至眼墙内侧宽缓过渡，眼墙外侧风速梯度陡峭，暴风圈内部向内缓慢增强。成熟台风暴风圈内雨量大致均匀、向内略增，进入眼墙时陡增并维持至眼区边缘；无眼系统向内增雨梯度更大。独立雨强主要调制暴风圈内降雨，轻微影响外围。所有参数都有滑动条；移动方向支持转盘。地图中心读数相对所选楼房，精调位置数值以海岸公寓为固定原点。",
    "html.text.221": "北半球环流逆时针并向内流入 15°。移动方向为去向：0° 向北、90° 向东。将移速的 65% 加入本地环流向量，形成前进方向右侧较强的危险半圆、左侧较弱的安全半圆。输入强度为静止参考值，移动叠加后本地风速可能超过它；“安全”仅是两侧的相对名称。",
    "html.text.222": "移速始终参与风场，点击“开始推进中心”才会自动移动中心。时间倍率 1–1000 倍同时改变模拟时钟、阵风与阵雨切换速度、风暴潮涨退及风毁累计受风时间，中心固定时也生效。全局暂停冻结天气、增水与中心移动。外围向内持续风和阵风阵雨出现频率逐渐增加，相对波动幅度逐渐减小。阵雨与阵风大体重合但不完全同步，极少数外围暴雨可超过眼墙，雨歇时偶有多云或晴空。外围边界内外概率连续：阵风保留弱背景事件，阵雨概率平滑降至零，圈外下沉晴空。“本地持续风”是参考平均值，“模拟阵风”反映瞬时气流。",
    "html.text.223": "风眼中心约 100 kt 雨停时，按设定的风眼半径与眼墙外界半径生成云墙；初期受到眼内厚云、平淡光照和散射遮挡，随后云隙与能见度提升才逐渐显露。内壁仅在风眼内显示，眼墙和暴风圈中由连续低云层覆盖天空；外围保留原有天空。坐标采用真实公里尺度；云底偏暗，云顶受光、向外倾斜，形成“体育场”状开口。强度越高云体越高、环形越完整，边缘仍有不规则起伏；从中心、边缘及高空观看会有不同远近和遮挡。云墙使用连续螺旋纹理，按最大风速 / 最大风速半径的角速度随模拟时钟逆时针转动，暂停时停止；眼内低层与中层云随强度增强逐渐消散，190 kt 起全部清空。强风雨下天空与楼房、山体雾色使用相同输出颜色空间，避免远景接缝。云墙起伏为视觉近似，非实测云高。参考 ",
    "html.text.224": "NOAA 飓风猎人的多里安风眼实拍",
    "html.text.225": "，未打包照片。自由飞行时，雨丝和运动雾带按空气运动减去相机运动计算相对速度，包含水平与升降；快速飞行会改变雨线的方向和长度，暂停天气后仍保留穿越静止雨幕的视差。",
    "html.text.226": "90–130 kt 时雨丝逐渐碎裂成风携碎雾，约 130 kt 近乎横行；强风雨下天空纹理淡去并融入雨雾。轻碎屑飞得更高、更贴近风速，大板片需要更强风才起飞，速度较慢且更低。弱系统中心保留雨；67–100 kt 眼内雨量连续减少，约 100 kt 眼中心趋于无雨，150 kt 左右开始见阳光，至 180 kt 逐渐晴朗，190 kt 起眼内低中云清空。简化增水随本地持续风增强，170 kt 约 3 米（约一层楼高度，实际淹深扣除地坪海拔），200 kt 约 4.3 米，上限 4.5 米；上涨时间常数为 40–65 模拟分钟；高水位在眼内继续保留，170 kt 台风需中心离开至少 500 km 后才开始缓慢回落，随后退水约需 6 模拟小时。时间倍率同时影响涨退。主界面与全屏均显示相对常态的当前水面上升米数、涨退趋势与速率。地形由步道、道路、住宅前场及更高台地组成，海拔逐级为 0.25、0.55、0.90、1.70、2.90、4.65 米。水面只升降，超过各级固定地形后自然淹入；台阶之间有短坡与楼梯，建筑落在对应地台上。白色色带与白斑模拟浪带和雨水击打，不计算波浪形变、破碎和真实水动力，增水数值仅用于视觉演示。",
    "html.text.227": "街景包含随风摆动的旗布、电线、草木及桶盖。环境杂物略减，吹海风时明显更少。树木、路灯和窗户的风毁门槛分别为 145、155、160 kt；超过门槛后按受风时间累计，风越强，能坚持的时间越短，各物体耐受力有差异。垃圾桶、路牌、护栏和旗布也会翻倒、飞走或变形。点击“恢复”修复景物并清除累计损伤，保留台风和水位；“重置”同时复位风暴与增水。全屏的“观测显示”可独立隐藏风速风向、雨量、水面和小地图；风速可切换持续风或阵风，地图可切换风速着色。",
    "html.text.228": "渲染：",
    "html.text.229": "Three.js r160",
    "html.text.230": "（MIT）。参考官方粒子示例，调研 ",
    "html.text.231": "Kenney City Kit",
    "html.text.232": "（未打包使用）。建筑、天气与地图均由程序生成；完整许可证附于 HTML。",
