    "guide.bind.UsageGuide.string.134e0fcf.0": "sidebar-collapsed",
    "guide.bind.groups.string.298f8bbc.0": ".control-group",
    "guide.bind.UsageGuide.string.40296205.0": "toggle",
    "guide.bind.UsageGuide.string.10a44713.0": "summary",
    "guide.bind.UsageGuide.string.5c7ea86f.0": "click",
    "guide.bind.behavior.string.299fbe89.0": "(prefers-reduced-motion:reduce)",
    "guide.bind.behavior.string.906871b2.0": "instant",
    "guide.bind.behavior.string.174f6af.0": "smooth",
    "guide.bind.UsageGuide.block.string.652b04df.0": "start",
    "guide.bind.steps.title.string.389fb081.0": "观察与环视",
    "guide.bind.steps.target.string.f99f4e3b.0": "#view",
    "guide.bind.steps.text.string.24c94003.0": "在视窗内单指拖动环视，双指捏合缩放。下方是观测点的风雨读数；页面下方“台风设置”展开参数。",
    "guide.bind.steps.text.string.6f1d6e75.0": "在视窗内按住鼠标拖动，或点击视窗后按方向键环视；滚轮缩放。下方是观测点读数，右侧“台风设置”展开参数。",
    "guide.bind.steps.title.string.57e5c564.0": "换楼房与楼层",
    "guide.bind.steps.target.string.bf004a64.0": ".observer-controls",
    "guide.bind.steps.text.string.6a09774b.0": "选择一座观测楼房，再拖动楼层滑条或输入楼层。不同地点和高度有不同的视野；自由飞行时先返回楼房，才能调节楼层。",
    "guide.bind.steps.title.string.99170de.0": "在地图定位风暴",
    "guide.bind.steps.target.string.849b1f17.0": ".map-section",
    "guide.bind.steps.group.string.849b1f17.0": ".map-section",
    "guide.bind.steps.text.string.7b1f30eb.0": "地图默认拖动平移，双指或滚轮缩放。先开启“移动风暴中心”，再点击或拖动设置中心；关掉开关后恢复平移。“楼群”可定位观测楼房。",
    "guide.bind.steps.title.string.9a8f46f3.0": "独立调节风与雨",
    "guide.bind.steps.target.string.45159650.0": ".intensity-section",
    "guide.bind.steps.group.string.45159650.0": ".intensity-section",
    "guide.bind.steps.text.string.61bd589c.0": "台风强度表示最大一分钟持续风，观测点读数还取决于距中心的位置。“独立雨强”可单独调节；风圈大小在“风圈结构”中设置。",
    "guide.bind.steps.title.string.4d635d5.0": "让风暴移动",
    "guide.bind.steps.target.string.82917eed.0": ".motion-section",
    "guide.bind.steps.group.string.82917eed.0": ".motion-section",
    "guide.bind.steps.text.string.46a3b612.0": "转盘设置移动去向，速度使用 kt。点击“开始推进中心”才会移动；时间倍率同时影响推进、阵雨阵风、风毁和风暴潮。暂停按钮可冻结天气。",
    "guide.bind.steps.title.string.a4c84c5.0": "自由飞行与去雾",
    "guide.bind.steps.target.string.98de3899.0": "#sceneToolbar",
    "guide.bind.steps.text.string.7f5f2e65.0": "点“上帝视角”进入自由飞行，用左侧摇杆水平移动，右侧“升 / 降”调高度。视角面板也有缩放、去雾、归中和恢复。",
    "guide.bind.steps.text.string.142791d5.0": "点“上帝视角”后，在视窗内用 WASD 水平移动、Q/E 升降，Shift 加速。“去除雨雾”只改善画面通透度，不改变气象读数。",
    "guide.bind.steps.title.string.4a6c7945.0": "水位与风毁",
    "guide.bind.steps.target.string.211f8026.0": ".status-row",
    "guide.bind.steps.text.string.970f676d.0": "水位、雨量在左，风毁数量和剩余坚持时间在右。损坏随风速和受风时间积累；“恢复”修复景物并重新计时，顶部“重置”会复位全部设置。",
    "guide.bind.steps.title.string.f61653af.0": "全屏观测",
    "guide.bind.steps.target.string.235b7437.0": "#fullscreen",
    "guide.bind.steps.text.string.d12391e3.0": "全屏中可单独开关读数和地图。“净览”隐藏覆盖层，仅留“显示”按钮恢复；退出全屏后随时从顶部重开使用指南。",
    "guide.bind.steps.text.string.b1451846.0": "点“全屏”专注观测。引导期间保留自由鼠标，完成后按 M 开关环视，Esc 释放鼠标。全屏菜单可选择读数和地图。",
    "guide.bind.tour.string.e562ab48.0": "div",
    "guide.bind.UsageGuide.string.116c7b0c.0": "guide-tour",
    "guide.bind.UsageGuide.string.95785cf2.0": "<div class=\"guide-spotlight\" aria-hidden=\"true\"></div><section class=\"guide-card\" role=\"region\" aria-label=\"交互式上手引导\" tabindex=\"-1\"><header><small id=\"guideProgress\"></small><button id=\"endTour\" aria-label=\"结束上手引导\">结束 ×</button></header><h2 id=\"guideStepTitle\"></h2><p id=\"guideStepText\" aria-live=\"polite\"></p><nav aria-label=\"引导步骤\"><button id=\"previousGuideStep\">上一步</button><button id=\"nextGuideStep\">下一步 →</button></nav></section>",
    "guide.bind.card.string.d9c20454.0": ".guide-card",
    "guide.bind.spot.string.7e7dfe5a.0": ".guide-spotlight",
    "guide.bind.position.UsageGuide.left.string.594e66b5.0": "px",
