    "wind-colors.createController.bind.WindColorScales.string.9a657f36.0": "paletteTitle",
    "wind-colors.createController.bind.WindColorScales.string.16337ad0.0": "<div class=\"section-heading\"><h2 id=\"paletteTitle\">风场色标</h2><button id=\"closePalette\">关闭 ×</button></div><p class=\"palette-help\">风速节点以 kt 为单位，颜色变化不改变风场。节点可增删；连续模式下相邻同速节点可形成颜色跳变。</p><label class=\"palette-label\">预设 / 我的色标 <select id=\"palettePreset\" aria-label=\"风场色标预设\"></select></label><div id=\"palettePreview\"></div><div class=\"palette-meta\"><label>名称 <input id=\"paletteName\" maxlength=\"60\"></label><label>插值 <select id=\"paletteInterpolation\"><option value=\"linear\">连续 RGB</option><option value=\"step\">分段色阶</option></select></label></div><div class=\"palette-node-head\"><span>风速 kt</span><span>颜色 / HEX</span></div><div id=\"paletteNodes\"></div><div class=\"palette-actions\"><button id=\"addPaletteNode\">添加节点</button><button id=\"savePalette\">保存到我的色标</button></div><p id=\"paletteMessage\" role=\"status\"></p><details class=\"palette-json\"><summary>导入 / 导出 JSON</summary><textarea id=\"paletteJson\" aria-label=\"风场色标 JSON\" spellcheck=\"false\" placeholder=\"粘贴风场色标 JSON\"></textarea><div class=\"palette-actions\"><button id=\"importPalette\">应用 JSON</button><button id=\"exportPalette\">生成 JSON</button></div></details>",
