    "app.initScene.waterMaterial.color.string.a3cd8c65.0": "#7a9091",
    "app.initScene.groundShader.string.f23cecd1.0": "float coastalGround(float x){if(x>=",
    "app.initScene.groundShader.string.c07b114e.0": ")return ",
    "app.initScene.groundShader.string.3e0cb6da.0": ";",
    "app.initScene.groundShader.string.d9a34c5f.0": "if(x>=",
    "app.initScene.groundShader.string.3b6b4f70.0": ")return mix(",
    "app.initScene.groundShader.string.290c95cb.0": ",",
    "app.initScene.groundShader.string.81cff459.0": ",(",
    "app.initScene.groundShader.string.683df0ec.0": "-x)/",
    "app.initScene.groundShader.string.16d79aad.0": ");",
    "app.initScene.groundShader.string.811c9dc5.0": "",
    "app.initScene.groundShader.string.305fb2ba.0": "return 4.65;}",
    "app.initScene.string.3fd4241e.0": "varying vec3 waterWorld;varying float coastalX;\n",
    "app.initScene.string.4dccc10b.0": "#include <worldpos_vertex>",
    "app.initScene.string.1532b5a1.0": "#include <worldpos_vertex>\nwaterWorld=(modelMatrix*vec4(transformed,1.0)).xyz;coastalX=waterWorld.x;",
    "app.initScene.string.5dd543c6.0": "varying float coastalX;uniform float coastalWaterLevel;\n",
    "app.initScene.string.f0c6cdd.0": "\n",
    "app.initScene.string.26cf636c.0": "#include <color_fragment>",
    "app.initScene.string.1521a22f.0": "#include <color_fragment>\nfloat waterDepth=max(0.0,coastalWaterLevel-coastalGround(coastalX));float shallowAlpha=.28+.65*(1.0-exp(-waterDepth*.9));diffuseColor.a*=mix(1.0,shallowAlpha,1.0-smoothstep(39.0,48.0,coastalX));",
    "app.initScene.template.2": "varying vec3 waterWorld;uniform float waterDay;uniform float waterClock;uniform vec3 waterSunDir;\n        float seaHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n        float seaNoise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(seaHash(i),seaHash(i+vec2(1.,0.)),f.x),mix(seaHash(i+vec2(0.,1.)),seaHash(i+vec2(1.,1.)),f.x),f.y);}\n      ",
    "app.initScene.string.e0fbb7a8.0": "#include <opaque_fragment>",
    "app.initScene.template.3": "vec3 waterView=normalize(cameraPosition-waterWorld);\n        float footprint=max(length(dFdx(waterWorld.xz)),length(dFdy(waterWorld.xz)));\n        float detail=1.-smoothstep(.8,4.5,footprint);\n        vec2 rippleCoord=vec2(waterWorld.x*.13+waterWorld.z*.045,waterWorld.z*.51-waterWorld.x*.12);\n        vec2 drift=vec2(waterClock*.18,-waterClock*.30);\n        float rippleA=(seaNoise(rippleCoord+drift)*2.-1.)*detail;\n        float rippleB=(seaNoise(rippleCoord*1.17+vec2(31.7,12.4)+drift)*2.-1.)*detail;\n        vec3 rippleNormal=normalize(vec3(rippleA*.09,1.,rippleB*.07));\n        float horizon=pow(1.-max(0.,dot(waterView,rippleNormal)),3.);\n        vec3 skyReflection=mix(vec3(.16,.40,.48),vec3(.48,.67,.75),horizon);\n        float reflectedSun=max(0.,dot(reflect(-waterSunDir,rippleNormal),waterView));\n        float sparkle=pow(reflectedSun,160.)*(.45+.55*pow(abs(rippleA*rippleB),.6));\n        float broadGlint=pow(reflectedSun,24.)*.09;\n        outgoingLight=mix(outgoingLight,skyReflection,waterDay*(.18+horizon*.48));\n        outgoingLight+=waterDay*vec3(1.,.90,.68)*(sparkle*2.7+broadGlint);\n        #include <opaque_fragment>",
