    "formula-reference.intro.string.f50c43ef.0": "p",
    "formula-reference.intro.string.d652ce15.0": "这里附上当前构建的全部第一方模拟源码、从源码自动提取的计算表达式，以及可编辑公式的变量与内置表达式。包括风雨、风场、能见度、风暴潮、眼墙、粒子、风毁、相机和地图。第三方 Three.js 不在此重复。此页为只读的内置参考；外部配置可改变实际运行数值和公式，修改请使用配置编辑器。",
    "formula-reference.intro.string.eb4ee1c2.0": "formula-reference-intro",
    "formula-reference.units.string.f50c43ef.0": "p",
    "formula-reference.units.string.5b5bef9f.0": "单位：风速 kt；模型距离 km；场景距离、水位与能见度 m；角度和时间以各式变量所在源码为准（包含 rad、度、模拟秒与分钟）。clamp(x,a,b)=max(a,min(b,x))；smooth(a,b,x)=t²(3−2t)，t=clamp((x−a)/(b−a),0,1)。",
    "formula-reference.units.string.eb4ee1c2.0": "formula-reference-intro",
